local Menu = {} local Camera = workspace.CurrentCamera local UserInputService = game:GetService("UserInputService") for _,v in Enum.KeyCode:GetEnumItems() do getfenv(0)[("VK_" .. tostring(v):gsub("Enum.KeyCode.", "")):upper()] = v end local FPS = 500; local Utility = { Connections = {}, Objects = {} }; Utility.__index = Utility; do function Utility:Connect(signal: signal, funct: func): connection local Connection = signal:Connect(funct); table.insert(self.Connections, Connection); return Connection; end function Utility:CreateDrawing(type: string): drawing_obj local Object = Drawing.new(type); table.insert(self.Objects, Object); return Object; end function Utility:Unload(): nil for _,v in self.Connections do v:Disconnect(); end end end local Renderer = { Cache = {}, Connections = {}, FPS = FPS }; Renderer.__index = Renderer; do function Renderer:Rectangle(id: string, pos: Vector2, size: Vector2, color: Color3, filled: boolean, zindex: number): drawing_obj local Object = self.Cache[id] or Utility:CreateDrawing("Square"); Object.Position = pos; Object.Size = size; Object.Color = color; Object.Filled = filled == nil and true or filled; Object.ZIndex = zindex or 1; Object.Visible = true; self.Cache[id] = Object; return Object; end function Renderer:Text(id: string, pos: Vector2, size: int, font: int, color: Color3, text: string, zindex: number): drawing_obj local Object = self.Cache[id] or Utility:CreateDrawing("Text"); Object.Position = pos; Object.Size = size; Object.Font = font; Object.Color = color; Object.Text = text; Object.ZIndex = zindex or 1; Object.Outline = true; Object.Visible = true; self.Cache[id] = Object; return Object; end function Renderer:TextSize(text: string, size: int, font: int): Vector2 local Object = Utility:CreateDrawing("Text"); Object.Font = font; Object.Size = size; Object.Text = text; Object.Visible = false; local TextSize = Object.TextBounds; Object:Remove(); return TextSize; end function Renderer:Connect(func: func): table local Connection = {}; table.insert(self.Connections, Connection); table.insert(Utility.Connections, Connection); Connection.Callback = func; function Connection:Remove(): nil table.remove(Renderer.Connections, table.find(Renderer.Connections, Connection)); end function Connection:Disconnect(): nil table.remove(Renderer.Connections, table.find(Renderer.Connections, Connection)); end return Connection; end function Renderer:Think(): nil for _,v in self.Connections do v.Callback(Menu); end end function Renderer:Clear(): nil for _,v in self.Cache do v.Visible = false end end coroutine.resume(coroutine.create(function() while (true) do Renderer:Clear(); Renderer:Think(); task.wait(1 / Renderer.FPS); end end)) end Menu = { Font = 2, Size = 13, Theme = { ["Outline"] = Color3.fromRGB(0, 0, 0), ["Inline"] = Color3.fromRGB(55, 55, 55), ["Background"] = Color3.fromRGB(25, 25, 25), ["Text"] = Color3.fromRGB(255, 255, 255), ["Dark Text"] = Color3.fromRGB(120, 120, 120), ["Accent"] = Color3.fromRGB(0, 125, 200), }, ConfigFlags = {}, Flags = {}, Index = 0, }; Menu.__index = Menu; do function Menu:Id(...): string local Args = {...}; local String = ""; for _,v in Args do String = String .. "_" .. v; end return String; end function Menu:GetTheme(name: string): Color3 return self.Theme[name]; end local LastInput = os.clock(); function Menu:Init(name: string, index: int, position: Vector2, size: int): metatable local Window = self.ConfigFlags[name] or { Index = index, Offset = 0, IndexCount = 0, }; if not self.ConfigFlags[name] then self.ConfigFlags[name] = Window; end local Position = position or Vector2.new(50, Camera.ViewportSize.y / 2); local Size = Size or 200; Window.Offset = 0; Window.AbsPosition = Position; Window.Position = Position + Vector2.new(5, 4); Window.Size = Size; Window.IndexCount = 0; local ZIndex = 0; local TextSize = Renderer:TextSize(name, Menu.Size, Menu.Font); local Outline = Renderer:Rectangle( Menu:Id(name, "outline"), Position, Vector2.new(Size, TextSize.y + 6), Menu:GetT