; end local Position = self.Parent.Position + Vector2.new(0, self.Parent.Offset); local Size = self.Size; local ZIndex = self.ZIndex; Label.Name = Menu:Id(self.Name, name); if (not self.Selected) then return setmetatable(Label, Menu); end local Text = Renderer:Text( Menu:Id(self.Name, name, "text"), Position, Menu.Size, Menu.Font, Menu:GetTheme("Text"), name, ZIndex + 1 ); self.Parent:AddSize(Text.TextBounds.y + 2); self.Parent.Offset += Text.TextBounds.y + 2; return setmetatable(Label, Menu); end function Menu:Toggle(name: string, status: boolean): metatable local Toggle = Menu.ConfigFlags[name] or { Status = status }; if not Menu.ConfigFlags[name] then Menu.ConfigFlags[name] = Toggle; end local Position = self.Parent.Position + Vector2.new(0, self.Parent.Offset); local Size = self.Size; local ZIndex = self.ZIndex; Toggle.Parent = self; Toggle.Name = Menu:Id(self.Name, name); Menu.Flags[name] = Toggle.Status; local function Set(bool: boolean) Toggle.Status = bool; end Toggle.Set = Set; if (not self.Selected) then return setmetatable(Toggle, Menu); end self.Parent.IndexCount += 1; Toggle.Index = self.Parent.IndexCount; local SelectedString = self.Parent.Index == Toggle.Index and "[/] " or ""; local Text = Renderer:Text( Menu:Id(self.Name, name, "text"), Position, Menu.Size, Menu.Font, Toggle.Status and Menu:GetTheme("Accent") or self.Parent.Index == Toggle.Index and Menu:GetTheme("Text") or Menu:GetTheme("Dark Text"), SelectedString .. name, ZIndex + 1 ); if (self.Parent.Index == Toggle.Index and UserInputService:IsKeyDown(VK_RETURN) and os.clock() - LastInput > 1 / 5) then LastInput = os.clock(); Set(not Toggle.Status); end self.Parent:AddSize(Text.TextBounds.y + 2); self.Parent.Offset += Text.TextBounds.y + 2; return setmetatable(Toggle, Menu); end function Menu:Slider(name: string, status: float, min: float, max: float, float: float): metatable local Slider = Menu.ConfigFlags[name] or { Status = status }; if not Menu.ConfigFlags[name] then Menu.ConfigFlags[name] = Slider; end local Position = self.Parent.Position + Vector2.new(0, self.Parent.Offset); local Size = self.Size; local ZIndex = self.ZIndex; Slider.Parent = self; Slider.Name = Menu:Id(self.Name, name); Slider.Min = min; Slider.Max = max; Slider.Float = float; Menu.Flags[name] = Slider.Status; local function Set(num: float) Slider.Status = math.clamp(num, min, max); end Slider.Set = Set; if (not self.Selected) then return setmetatable(Slider, Menu); end self.Parent.IndexCount += 1; Slider.Index = self.Parent.IndexCount; local SelectedString = self.Parent.Index == Slider.Index and "[/] " or ""; local Text = Renderer:Text( Menu:Id(self.Name, name, "text"), Position, Menu.Size, Menu.Font, self.Parent.Index == Slider.Index and Menu:GetTheme("Text") or Menu:GetTheme("Dark Text"), SelectedString .. name .. " - " .. string.format("%.3f", Slider.Status), ZIndex + 1 ); if (self.Parent.Index == Slider.Index and UserInputService:IsKeyDown(VK_RIGHT) and os.clock() - LastInput > 1 / 10) then LastInput = os.clock(); Set(Slider.Status + float); end if (self.Parent.Index == Slider.Index and UserInputService:IsKeyDown(VK_LEFT) and os.clock() - LastInput > 1 / 10) then LastInput = os.clock(); Set(Slider.Status - float); end self.Parent:AddSize(Text.TextBounds.y + 2); self.Parent.Offset += Text.TextBounds.y + 2; return setmetatable(Slider, Menu); end function Menu:HandleInput(window: metatable): nil if not isrbxactive() then return; end; if (UserInputService:IsKeyDown(VK_DOWN) and os.clock() - LastInput > 1 / 5) then LastInput = os.clock(); window.Index += 1; end if (UserInputService:IsKeyDown(VK_UP) and os.clock() - LastInput > 1 / 5) then LastInput = os.clock(); window.Index -= 1; end if (window.Index > window.IndexCount) then window.Index = 1; end if (window.Index < 1) then window.Index = window.IndexCount; end end end
